package clyvr.view;
import clyvr.controller.*;import clyvr.model.Entities.*;import clyvr.ui.*;import javax.swing.*;import java.awt.*;
public class RequestQueueView extends JPanel {
 public RequestQueueView(AppController app){super(new BorderLayout());JPanel p=ViewSupport.page("Request review","Receptionist queue · approvals and reasoned rejections");int count=0;app.store.expire();for(Appointment a:app.store.appointments)if(a.status==Status.PENDING_RECEPTIONIST){count++;JButton approve=Theme.button("Approve");approve.addActionListener(e->{try{app.store.decide(a,true,"");app.refresh();}catch(Exception ex){app.error(ex.getMessage());}});JButton reject=Theme.secondary("Reject");reject.addActionListener(e->{String reason=ViewSupport.reasonDialog(this);if(reason!=null){app.store.decide(a,false,reason);app.refresh();}});ViewSupport.line(p,ViewSupport.display(app,a),ViewSupport.detail(a),approve,reject);}
  p.add(Theme.label("Doctor time-off requests",18,true));Theme.space(p,12);for(TimeOff t:app.store.timeOffs)if(t.status==TimeOffStatus.PENDING){count++;JButton approve=Theme.button("Approve");approve.addActionListener(e->{try{app.store.decideTimeOff(t,true,"");app.refresh();}catch(Exception ex){app.error(ex.getMessage());}});JButton reject=Theme.secondary("Reject");reject.addActionListener(e->{String reason=ViewSupport.reasonDialog(this);if(reason!=null){app.store.decideTimeOff(t,false,reason);app.refresh();}});ViewSupport.line(p,app.store.doctorName(t.doctorId)+" · Time off",t.day+" · "+clyvr.model.ClinicStore.TIMES[t.slot],approve,reject);}
  p.add(Theme.label("Cancellation and reschedule requests",18,true));Theme.space(p,12);
  for(ChangeRequest r:app.store.changeRequests)if(r.pending){count++;JButton approve=Theme.button("Approve");approve.addActionListener(e->{try{app.store.resolveChange(r,true,"");app.refresh();}catch(Exception ex){app.error(ex.getMessage());}});JButton reject=Theme.secondary("Reject");reject.addActionListener(e->{String reason=ViewSupport.reasonDialog(this);if(reason!=null){app.store.resolveChange(r,false,reason);app.refresh();}});ViewSupport.line(p,r.kind+"  •  "+r.appointmentId,"Requested by "+app.store.user(r.requesterId).name()+"  •  "+r.details+(r.proposedDay==null?"":"  →  "+r.proposedDay+"  ·  "+clyvr.model.ClinicStore.TIMES[r.proposedSlot]),approve,reject);}
  if(count==0)p.add(ViewSupport.empty("No requests are awaiting receptionist review."));add(ViewSupport.wrap(p));}
}
